def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    high_threat = 0
    medium_threat = 0
    desperate_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 100:
                    high_threat += 1
                elif bid >= 70:
                    medium_threat += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    if prev_bids:
        top_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        top_prev = 0.0
        avg_prev = 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if no_water_days >= 2 or hp <= 3:
        urgency = 3
    elif no_water_days >= 1 or hp <= 5:
        urgency = 2
    elif hp <= 7:
        urgency = 1

    if urgency == 3:
        bid = max(92.0, top_prev + 2.0)
        if scarcity == 2:
            bid = max(bid, 108.0)
        elif scarcity == 1:
            bid = max(bid, 98.0)
    elif urgency == 2:
        if top_prev >= 105:
            bid = 96.0 if scarcity >= 1 else 82.0
        elif top_prev >= 85:
            bid = min(95.0, top_prev + 1.5)
        else:
            bid = 72.0 if scarcity >= 1 else 58.0
    elif urgency == 1:
        if scarcity == 2 and desperate_count >= 1:
            bid = 66.0
        elif top_prev >= 100:
            bid = 28.0
        elif top_prev >= 80:
            bid = 44.0
        else:
            bid = 36.0
    else:
        if scarcity == 2 and desperate_count >= 2:
            bid = 30.0
        elif top_prev >= 100:
            bid = 12.0
        elif avg_prev >= 70:
            bid = 18.0
        else:
            bid = 24.0

    remaining_days = max(0, 10 - day)
    reserve = remaining_days * 22.0
    if urgency <= 1 and budget < reserve:
        bid = min(bid, 20.0)
    elif urgency == 2 and budget < reserve:
        bid = min(bid, 72.0)

    if day >= 8:
        if urgency >= 2:
            bid += 8.0
        elif hp <= 6:
            bid += 4.0

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents, just buy enough to stay alive.
    if not alive_opps:
        target = WATER_REQ if supply >= WATER_REQ else supply
        return float(min(budget, max(0.0, target)))

    # Read yesterday bids to infer aggressiveness.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Determine our needed urgency.
    urgency = 0.0
    if hp <= 2:
        urgency += 0.9
    elif hp <= 4:
        urgency += 0.6
    elif hp <= 6:
        urgency += 0.3

    if no_water_days >= 2:
        urgency += 0.6
    elif no_water_days == 1:
        urgency += 0.3

    # Supply pressure: when supply is low, water is scarce; bid more.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    scarce_factor = 1.0 - max(0.0, min(1.0, supply_ratio))  # 1 when low supply

    # Base bid: aim to be competitive but not match extreme bids.
    # Cindy's ~112.5 suggests others can go high; we use a fraction of that.
    if highest_prev_bid >= DAILY_SALARY * 1.0:
        base = max(avg_prev_bid * 0.6, highest_prev_bid * 0.45)
    else:
        base = max(avg_prev_bid * 0.55, DAILY_SALARY * 0.5)

    # Adjust by urgency and scarcity.
    bid = base * (1.0 + 0.9 * urgency * 0.6 + 0.8 * scarce_factor)

    # Keep within budget and avoid overbidding when budget is tight.
    # Also cap to ~1.2x salary to reduce variance.
    cap = max(0.0, min(budget, DAILY_SALARY * 1.2))
    bid = min(bid, cap)

    # If budget is very low, bid what we can.
    if budget <= 0.0:
        return 0.0

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

